def suppliers_to_vendors(apps, schema_editor):
    """Each distinct supplier name becomes a vendor, linked from its materials."""
    Material = apps.get_model("shop", "Material")
    Vendor = apps.get_model("shop", "Vendor")
    for material in Material.objects.exclude(supplier=""):
        name = material.supplier.strip()
        if name:
            vendor = Vendor.objects.filter(name__iexact=name).first() or Vendor.objects.create(
                name=name
            )
            material.vendor = vendor
            material.save(update_fields=["vendor"])


def vendors_to_suppliers(apps, schema_editor):
    Material = apps.get_model("shop", "Material")
    for material in Material.objects.exclude(vendor=None).select_related("vendor"):
        material.supplier = material.vendor.name[:100]
        material.save(update_fields=["supplier"])


